        [1302] = {
            ["저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?"] = "8235974cfa833adfdaf9b2864225d19f",
        },
        [1303] = {
            ["저희 가게에서는 스톰윈드 각지에 싱싱한 꽃을 독점 공급하고 있습니다. 어디에나 잘 어울리고 동부 왕국 어디서도 찾을 수 없는 아름다운 꽃이죠. 천천히 둘러보시면서 꽃 향기에 흠뻑 취해보시는 게 어떨까요?"] = "529a618c35100390b17d2f2740d430aa",
        },
        [1304] = {
            ["달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠답니다. 하지만 루칸 코르델과 다른 직업 용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 찾는 물건이 있으면 언제든지 말씀해 주시기 바랍니다."] = "52ce57327118edf04bd3864c3342a693",
            ["달라란이 몰락하고 쿠엘탈라스가 멸망한 후로 이런 종류의 물건을 손에 넣기가 매우 어려웠습니다. 하지만 루칸 코르델과 다른 직업 용품 상인들이 우리 주문에 따라 아주 질 좋은 물건들을 잘 공급해 주고 있답니다. 특별히 찾으시는 물건이 있으십니까?"] = "52ce57327118edf04bd3864c3342a693",
            ["저는 스톰윈드 최고의 장인들과 마법사가 만든 최고의 물건만을 팔고 있습니다. 천천히 둘러보시기 바랍니다."] = "2e4eca05cb76135045a9a7c0e66e45af",
            ["저는 이곳 스톰윈드의 장인과 마법사가 만든 최고의 마법 장비만을 팔고 있습니다. 원하시는 물건이 있으시면 말씀해 주시기 바랍니다."] = "2e4eca05cb76135045a9a7c0e66e45af",
        },
        [1305] = {
            ["내가 충고 한마디 해 드릴까? 어둠은 가까이하지 않는 게 좋을 것이오."] = "f74e7d5a245870415207560edfabf06d",
