        [15561] = {
            ["장로 그레이브본은 티리스팔 숲의 브릴 근처에서 지내고 있네."] = "8aa7da319f4642917680c8b017576c28",
            ["장로 문스트라이크는 서부 역병지대의 스칼로맨스에서 찾을 수 있네."] = "969acaf245ed6f2b05bdbb672a4a18c9",
            ["장로 하이피크는 동부 내륙지 중앙에 있는 언덕에서 정찰을 하고 있을 걸세."] = "caf07620c72127b10e1729b5a72eef6b",
            ["해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
        },
        [15562] = {
            ["장로 럼버락은 불타는 평원의 우레망치 바위굴 꼭대기에 있는 동굴에서 몇 년째 지내고 있네."] = "9f8adafc093f04bb044f1e110b7ea3ac",
            ["장로 브론즈비어드는 선조 때부터 이어진 브론즈비어드 가문의 고향, 아이언포지에서 찾을 수 있네."] = "f65717b9ef7e2cce484130fee81dd53a",
            ["장로 블레이드스위프트는 텔드랏실 위쪽에 있는 다르나서스의 길을 따라 거닐고 있네."] = "7b97edf23dc2c013612ec1169de003d7",
            ["장로 스톰브로우는 엘윈 숲의 골드샤이어 마을에 있을 거라네."] = "0ef3a4daeaac64acf2ca98fcf3350b69",
            ["해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
        },
        [15563] = {
            ["내가 마지막으로 기억하기로 장로 스타송은 슬픔의 늪의 가라앉은 사원에 있었네."] = "4c3e419f5e2712f60d981727a7b7fb3d",
            ["해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
