        },
        [15767] = {
            ["안녕하십니까, $C|1이여;여;? 저는 썬더 블러프를 위해 일하고 있는 인사 장교입니다. 호드 무공 훈장을 받은 모험가들을 돕는 것이 제 임무입니다.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하시는 것이 가장 좋습니다. 제게 훈장을 주시면 당신의 공적을 기록해 두겠습니다. 그렇게 되면 썬더 블러프에서 당신의 임무 수행 능력에 대한 인정을 받게 될 것입니다."] = "65414b48556b1233b03316c19af1740a",
        },
        [15768] = {
            ["안녕하신가, $C|1이여;여;? 나는 언더시티를 위해 일하고 있는 인사 장교라네. 호드 무공 훈장을 받은 모험가들을 돕는 것이 내 임무지.$B$B꼭 몇 개를 모아와야 한다는 법은 없지만 10개를 한꺼번에 교환하는 것이 가장 좋다네. 내게 훈장을 주면 자네의 공적을 기록해 두도록 하지. 그렇게 되면 언더시티에서 자네의 임무 수행 능력에 대한 인정을 받게 될 것일세."] = "785ab4fc105ad5b95f78d5dd7a0e36e2",
        },
        [15797] = {
            ["거대괴수의 힘에 감춰진 비밀을 밝힐 수만 있다면 과학에 일대 혁신이 일어날 거예요!"] = "789dcc606ef711b511ee12ddff2c8186",
        },
        [15798] = {
            ["거대괴수를 연구하고 이해하게 된다면 퀴라지와 싸움에서 유리한 위치를 차지할 수 있습니다."] = "ca9c2a76280fa526355a744dfbdacd34",
        },
        [15799] = {
            ["퀴라지가 그 짐승들에게 뭘 먹이는지 알아내야 합니다! 그 짐승들의 크기를 보십시오!"] = "392d38d469784b0930ac72d8954f8d8e",
        },
        [15864] = {
            ["선조를 공경하는 것은 그대의 문화와 동족을 명예롭게 하는 일입니다. 선조의 주화는 이러한 공경심을 지닌 이들을 구분할 수 있는 중요한 역할을 합니다.$B$B이번 달의 축제 동안 여러 선조의 명예를 드높일 기회를 얻게 될 것입니다. 그러면 선조의 주화를 얻을 수 있지요. 제게 선조의 주화를 가져오시면 독특한 물건들로 그대의 성실함에 보답하겠습니다."] = "5ff684abf73ab59dca0e0d04d8c6f804",
            ["오멘은 엘룬아라 호수의 깊은 곳에 잠들어 있습니다만 스톰레이지 지하굴 근처, 남동쪽 비탈에 소환될 겁니다. 거기에서 그대는 특별한 연발탄 발사대를 찾게 될 겁니다...$B$B발사대에서 폭죽을 사용하면 오멘의 부하들이 올 겁니다. 폭죽을 대략 30개 정도 더 발사하거나 엘룬의 양초를 오멘의 부하들에게 발사하면 곧 오멘이 깨어날 겁니다."] = "8380da37ec60070f5cc0417fd12e3bc6",
        },
        [15871] = {
            ["장로 골드웰은 던 모로의 카라노스 마을에서 지내고 있네."] = "11ccf478d11d91ad3de1ce0965dd1e7c",
            ["장로 블레이드스위프트는 텔드랏실 위쪽에 있는 다르나서스의 길을 따라 거닐고 있네."] = "7b97edf23dc2c013612ec1169de003d7",
            ["장로 아이언밴드는 이글거리는 협곡의 검은재 동굴에 살고 있네."] = "6954eeb9a527a8cef8cc62722874280a",
            ["장로 해머스타우트는 스톰윈드의 성벽 안에서 찾을 수 있네."] = "24e765cdee4370c4b56804eb47e7701f",
            ["해가 바뀌고 달빛이 환하게 비추는 시간이 왔도다.$B$B고대인이 깨어나면... 우리의 시간이다."] = "98f6f474b4727ae3900b6c9cf1de0ff7",
        },
        [15895] = {
            ["안녕하세요, $N. 우리는 달의 축제의 정신을 널리 전파하기 위해 멀리 달의 숲에서 왔답니다.$B$B축제에 참여하시는 게 어떻겠습니까?"] = "aa03e1f2960fa0bfc11594e3485ca65b",
        },
        [15900] = {
            ["안녕하세요, $N. 우리는 달의 축제의 정신을 널리 전파하기 위해 멀리 달의 숲에서 왔답니다.$B$B축제에 참여하시는 게 어떻겠습니까?"] = "8c264afdfd859dd75aa92958ab0ec315",
        },
        [15903] = {
            ["그들은 말했소. '전쟁 물자를 모으는 임무를 훌륭히 완수했군. 자네도 진급할 때가 된 것 같은데...' 하지만, 이 말의 진짜 의미는 이거였소! '칸스, 자네를 땀 냄새나는 드워프 무리와 함께 실리더스의 벌레집 외곽으로 전출하는 바이네.'$B$B진급?! 훗, 정말 눈물 나게 고맙지 뭐요."] = "668e49c17df4b9aa59370244f97c3f6a",
        },
        [15905] = {
            ["다음 불꽃놀이를 놓치지 마십시오! 저녁 6시부터 벌어지는 놀라운 구경거리랍니다."] = "9e44a7a2990575244bfb03e10d9172dd",
            ["불꽃놀이가 끝난 후에는 술잔이 나옵니다. 모두 들어올려 건배하며 축제의 기쁨을 함께합시다!"] = "6d7a0a461e2650661f34cbb62df4a64c",
            ["이 술통 안에 무얼 넣었는지는 잘 모르겠지만 정말 꿀처럼 감미롭게 넘어갑니다!"] = "73bf520ba54e6d1e7f123875ac134dc2",
            ["지금 딱 키스를 선물 받는다면 정말 좋겠는데요? 옆구리 허전하신 분 어디 없을까요?"] = "4bf540b1bbdebcaec03285d831690899",
            ["친구여, 만나서 반갑습니다!"] = "229605db995a9c242cc65986e5928a1b",
        },
        [15906] = {
            ["다음 불꽃놀이를 놓치지 마십시오! 저녁 6시부터 벌어지는 놀라운 구경거리랍니다."] = "9946d1873a48e8fbc8fac8ab278eb276",
            ["불꽃놀이가 끝난 후에는 술잔이 나옵니다. 모두 들어올려 건배하며 축제의 기쁨을 함께합시다!"] = "ed03fb23ae16fb04599c13080c1acffe",
            ["이 술통 안에 무얼 넣었는지는 잘 모르겠지만 정말 꿀처럼 감미롭게 넘어갑니다!"] = "8667d501338eab68c0b14814dab835dd",
            ["지금 딱 키스를 선물 받는다면 정말 좋겠는데요? 옆구리 허전하신 분 어디 없을까요?"] = "bafd33062e7a5ef7f88bd3ac468a4a2e",
            ["친구여, 만나서 반갑습니다!"] = "43ccb729b1ae428d1ed345812ed65bd0",
        },
        [15907] = {
            ["불꽃놀이 후엔, 테이블에 술잔이 가득할 거라 들었습니다. 축배를 들 수 있는 멋진 술잔이지요!"] = "ed962dfa7d7188507f9a08ba0eb16209",
            ["썬더 블러프의 최정상에서 불꽃 놀이가 6시에 펼쳐집니다!"] = "c5f7e2df05ba63b220570cf049a0ae7a",
            ["안녕하세요, $c씨! 축제에 오신 것을 환영합니다!"] = "82e1f388e3d1053dc0d340f63090e225",
            ["지금 딱 키스를 선물 받는다면 정말 좋겠는데요? 옆구리 허전하신 분 어디 없을까요?"] = "e46a99e660cce12f8a4292fdb7f7bc29",
            ["파티 맥주통에 독한 맥주가 가득합니다. 술과 친구 그리고 축제 분위기가 가득하군요!"] = "06f49d9f9d5fb1edcf209836d4309855",
        },
        [15908] = {
            ["불꽃놀이 후엔, 테이블에 술잔이 가득할 거라 들었습니다. 축배를 들 수 있는 멋진 술잔이지요!"] = "c6b790a30cea1e9602b2204c2fdef80a",
            ["썬더 블러프의 최정상에서 불꽃 놀이가 6시에 펼쳐집니다!"] = "1732c988c271232a750d3e2e53c1d1d6",
            ["안녕하세요, $c씨! 축제에 오신 것을 환영합니다!"] = "9031ad552c6f16d0a461e40e557acbd7",
            ["지금 딱 키스를 선물 받는다면 정말 좋겠는데요? 옆구리 허전하신 분 어디 없을까요?"] = "25be0d84e393ee3ed1191d398a602628",
            ["파티 맥주통에 독한 맥주가 가득합니다. 술과 친구 그리고 축제 분위기가 가득하군요!"] = "a1266790d643e961d1a1d9572db705d7",
        },
        [15909] = {
            ["전 오빠와 마찬가지로 선조의 은혜를 기리는 분들을 높이 삽니다. 특히, 달의 축제의 대의를 충실히 따르는 분들에게 저의 기술을 전수할 수 있다는 것은 커다란 기쁨이지요."] = "63da9bd89a3205deec3a0d71f3209f77",
        },
        [15917] = {
            ["그대의 선조께서 그대를 축복하시길, $n님. 그리고 다가오는 해에도 행운이 깃들기를..."] = "5e8efcc987de096a86113fbf1f74025c",
            ["그들이 달의 축제가 마감됨을 전하면서 이 초롱들을 끌 것입니다."] = "7e9c620ca526252a37ea37761109af3c",
            ["달의 축제의 마지막 밤이로군요. 행운이 그대와 함께하기를!"] = "ea6aed234baf22eb98af03d184469b13",
            ["밤새도록 폭죽 축제가 펼쳐질 겁니다. 저녁 6시부터 새벽까지, 엘룬아라 호수를 건너 하늘이 밝게 빛나게 될 겁니다."] = "3ebd4c9fbc15b539397a05f7c7e9bfb7",
        },
        [16012] = {
            ["자비로운 스랄께서는 친절하게도 그의 영역 안에 날 위한 피난처를 마련해 주셨소. 하지만, 너무 오래 머물러 폐를 끼치고 싶지는 않소이다. 나로 인해 우리의 지도자에게 어떤 문제라도 생긴다면 정말 수치스러운 일이 아닐 수 없소."] = "b9ca2ade5c180a21e305ffe165d2771c",
        },
        [16013] = {
            ["시선을 너무 많이 끌지 않도록 하세요. 저는 국왕 폐하께서 알현을 허락해 주시기를 기다리고 있답니다. 기다리는 일만 아니라면 주위에 듬직한 경비병들이 있으니 꽤 안전하다는 생각이 드네요."] = "f555efebf575408048587026c0aa3577",
        },
        [16014] = {
            ["반갑네, 친구! 심령체 충전기에 대해 설명을 좀 해 볼까? 아니면 정밀하고도 근사한 무지향성 심령 융화기는 어때?"] = "2ee56c2d70a0c3bb5d140a53ddd3fa45",
        },
        [16031] = {
            ["$n, 이제 저는 괜찮을 테니 제 걱정은 마세요. 이 방에서 정화 의식을 치른 후 여기서 벗어날 수 있는 방법을 찾을 겁니다. 사악한 마법이 이곳을 더럽히고 있어요."] = "79424cf61ac27a09aeb2a6d5ab3cbd8e",
        },
        [16032] = {
            ["무슨 일이죠? 지금 바쁜 거 안 보입니까?"] = "360a69edd614799c733b1184cf582009",
        },
        [16033] = {
            ["$N! 제 말벗을 해주려고 돌아왔다고요? 정말 사려 깊은 친구로군요. 그리고 그 옷을 입고 있으니 당신 정말 멋진데요!$B$B다시 만나 얼마나 반가운지 모를 거예요. 여기 있으면 대부분 날 볼 수 없고 또 이것저것 다른 이유로 정말 외롭거든요, 이해하시죠? 당신이 우리 모두에게 해준 일은 정말 위대한 것이었어요. 절대 잊지 않을게요!$B$B일부러 찾아와 말동무가 되어줘서 고마웠어요. 그럼 자주 들려주세요!"] = "31cec36e221c24d2e395f87f8a13b7c7",
            ["<의심스러운 눈초리로 당신을 쏘아보다가 얘기를 계속하는 보들리>$B$B결국, 우리는 마법책을 손에 넣었지요. 그때 머리가 둘 달린 우리의 오우거 강령술사 코르모크의 네 개의 눈빛이 이상하게 변했어요. 정말 소름끼치는 장면이었죠. 두 번째 머리에 달린 눈은 꼭 죽은 자의 것과 같았거든요. 소의 눈처럼 말이에요. 상상이 가시죠? 그러다가 그가 갑자기 팔을 뻗어 발타라크가 걸고 있던 아뮬렛을 벗겨내지 뭐예요.$B$B나머지 동료들은 난리가 났죠. 우리 중 일부는 아뮬렛을 그대로 두라고 외쳐댔지만… 아뮬렛을 독차지하려는 자들도 있었답니다."] = "e4059edbada4f015b06e754a44f9b6c5",
            ["그 후, 우리는 헤어졌어요. 그게 전부랍니다. 쓸데없는 피를 너무 많이 흘렸나봐요... 어느 정도는 예정된 일이었다고 생각해요. 그리고 아뮬렛은 고생만 잔뜩 하게 하는 아무짝에도 쓸모없는 것이었죠.$B$B이후로 발타라크의 노예들은 우리를 하나씩 제거했어요. 아뮬렛 조각을 지니고 있던 이들은 대부분 죽어 영혼까지 아뮬렛에 담긴 발타라크의 영혼 조각에 의해 오염되었죠.$B$B당신이 여기 온 것에 내가 기뻐하는 이유가 바로 그 때문이에요, $n. 당신이 도와준다면 아뮬렛을 다시 하나로 합쳐 군주 발타라크에게 돌려줄 수 있을 테니까요!"] = "69ab7dc25b9198ce90439c7c1d193e0e",
            ["그래, 거기까지 했었죠.$B$B그래서 우리는 검은바위 첨탑의 상층부 깊숙한 곳까지 잠입했었죠. 그곳의 주인이자 사령관을 목표로 해서요. 바로 드라키사스 말입니다. 왜 그런 현명하지 못한 임무를 맡았느냐고 묻고 싶은 건가요? 당신이 만났던 우리 대장 안시온 하몬님은 도전을 좋아하는 사람이었답니다.$B$B놀랍게도 발타라크의 뻣뻣하게 굳은 손가락이 마법책을 꺼낼 때까지는 모든 일이 순조롭게 진행되었죠. 하지만, 그 후로 일이 꼬이기 시작했어요.$B$B계속 얘기할 필요가 있을까요? 당신 눈이 가물가물하는 것 같은데..."] = "c5bc7008b7dc8feccc3dc8a43b1ab1a8",
            ["내가 보여요? 아무도 날 볼 수 없었는데! 내가 여기서 얼마나 외로웠는지 모르실 거예요. 마침내 말동무가 생기다니 얼마나 즐거운지 몰라요!$B$B나의 옛 용병군단 중 살아남은 누군가가 보냈겠죠. 맞죠? 당연히 그렇겠죠!$B$B새로 생긴 말동무와 오래 대화를 나누고 싶지만 어서 이 사태부터 바로잡아야 해요. 군주 발타라크에게 그의 영혼을 돌려주려면 우린 할 일이 너무 많아요!"] = "d8a5cf6d252aa70c9685e327fb97066f",
            ["말하자면, 아주 간단해요, $n. 내가 예전에 참여했던 용병단인 감춰진 칼날단은 좋지 않은 시기에 잘못된 임무를 맡았어요.$B$B그렘닉 리즐스프랭이라는 무법항의 고블린 마법사가 우리를 고용했는데 군주 발타라크의 마법책에 욕심이 아주 아주 많았답니다. 아니면 오래된 경쟁 관계라도 있었던 것일까요? 어쨌든 이제 그 이유는 알 수가 없게 되었어요. 얼마 전 그렘닉이 발타라크의 암살자 유령에게 살해되었거든요. 암살자 유령들이 떼로 덤비면 굉장히 위험해요.$B$B음... 내가 어디까지 말했죠?"] = "719549680790d3f20c149ecbf7c7c9a1",
            ["이봐요, 그렇게 재촉하지 마세요! 어쨌든 내 얘기는 거의 끝났어요.$B$B그래서 우리는 모두 그 거대한 방의 한가운데에서 아뮬렛을 놓고 싸우기 시작했답니다. 그 안이 얼마나 난장판이 되었을지 상상이 가시죠? 결국, 아뮬렛은 세 조각으로 부서졌고 그곳에는 제각기 서로 다른 목적으로 온 자들이 있었기에 우리는 주사위를 굴렸답니다.$B$B나머지 이야기는 좀 우울해요. 왜냐하면, 그 때 즈음 발타라크의 영혼이 암살자 유령들을 소환하기로 결심했거든요."] = "58af390eae1d4f73c7b54ed1448a76db",
            ["조급해 하지 마세요!$B$B<살아 있는 자들은 참을성이 부족하다고 낮은 소리로 불평하는 보들리>$B$B앞서 말했듯이 군주 발타라크의 영혼과 강령술로 소환한 그의 암살자 유령들이 우리를 공격하기 시작했어요. 그때, 우리는 도저히 맞서 싸울 수 있는 상태가 아니었기에 달아나기 시작했죠. 아직도 생생히 기억나는군요. 우리 드루이드 중의 하나인 모르 그레이후프가 그만 미끄러져서 첨탑의 하층부로 떨어지고 말았답니다.$B$B나머지는 당신이 알고 있는 그대로고요."] = "6952da64d9a42837f0f8a0e8e30b1e67",
        },
        [16070] = {
            ["안녕하신가? $C 양반, 우리 만난 적이 있던가? 얼마 전 어떤 행사에서 말이야... 낯익은 얼굴이긴 한데 이 도시가 워낙 혼잡한 곳이라서 말이지.$B$B그 특별한 모임에 참석했다면 분명 비밀 번호도 받았을 테지. 그걸 내게 알려주면 특별한 상품을 주겠네."] = "c5afae87abc614718a9d01193dc59430",
        },
        [16076] = {
            ["안녕하신가? $C 양반, 우리 만난 적이 있던가? 얼마 전 어떤 행사에서 말이야... 낯익은 얼굴이긴 한데 이 도시가 워낙 혼잡한 곳이라서 말이지.$B$B그 특별한 모임에 참석했다면 분명 비밀 번호도 받았을 테지. 그걸 내게 알려주면 특별한 상품을 주겠네."] = "28755471b38e6eb285e0d80db6c9498a",
        },
        [16091] = {
            ["모험가여, 안녕하십니까! 라벤홀트 장원의 토박이가 이렇게 인사 올립니다."] = "a71a88515d6fa1bcf5501c0265097b6d",
        },
        [16112] = {
            ["빛의 결사단이 뭐냐고? 음... 우리는 뼛속까지 철저한 은빛 여명회의 일원이오. 모두 도덕이나 죄의식, 쓸데없는 인간의 감정 따위에 결코 흔들리지 않소이다. 붉은십자군에서 멍청함, 지도력의 부재, 맹목적인 광신을 뺀 것이 우리의 모습이라고 생각하면 될 것이오.$B$B붉은십자군 사령관의 말은 듣지 마시오.$B$B그리고 티로서스에게 내가 이런 말을 했다고 하지 마시오... 만약 그 때문에 다툼이 벌어져 그를 잔인하게 해치게 된다면 정말 수치스러운 일이 아닐 수 없으니까."] = "087fc685b3d3b988443256863a127d39",
            ["아직도 논란이 되고 있는 그의 죽음 이후 로데론의 기사와 전사들은 고인이 된 영웅을 기리는 의미로 그와 비슷한 방어구를 만들어 입기 시작했소. 켈투자드를 상대로 모그레인은 목숨까지 바쳐 위대한 승리를 거두었고 그의 죽음으로 인해 촉발된 희생 정신은 전쟁이 끝날 때까지 그칠 줄 몰랐소.$B$B한 명이 쓰러지자 수많은 사람이 들고 일어났지…"] = "338d2b414e7e0fbcec01d970b4aa4241",
            ["진심으로 묻는 거요? 정말 모른단 말이오?$B$B겁이 많은 편이라면 불타는 평원과 이글거리는 협곡에 사는 생물들에서 검은무쇠 조각을 찾는 것이 좋을 거요.$B$B유혈이 난무하는 모험을 즐기는 편이라면 검은바위 첨탑과 검은바위 나락의 던전으로 가시오. 엄청난 양의 검은무쇠 조각을 얻을 수 있을 것이오."] = "0b31ddefd183ea40f98d3eae3fd516ca",
            ["첫 번째로 만든 무쌍의 전투장비는 붉은십자군 대영주 모그레인만을 위한 것이었소. 대영주가 무쌍의 전투장비를 입고 있으면 황천 깊숙이 있는 악마와 다름없는 모습이었지.$B$B그렇소, 모그레인이 파멸의 인도자를 높이 들고 백 명의 스컬지에게 뛰어들었다가 반대편에서 먼지와 화염 구름을 뚫고 나오는 모습은 정말 장관이었소. 적들은 그의 발 아래 재로 변했지."] = "d0454cc1a7f4f7f1c3d786915dd2f879",
        },
        [16113] = {
            ["리치 왕이 이 세계에 모습을 드러내려 합니다. 절대로 이를 용납해서는 안 됩니다."] = "2546edb7adcfdf6f1c9a8e4e04303b07",
            ["신념… 어떤 이들은 잃고 어떤 이들은 찾지요. 파괴할 수도 없고 만들어 낼 수도 없는 것입니다.$B$B앗, 혹시 신념의 의복 말씀입니까? 그 의복은 마지막 전쟁 동안 스컬지와의 전투에서 우리 사제들과 신앙심이 두터운 전사들이 입었지요.$B$B네, 신념의 의복은 거의 다 사라졌습니다… 낙스라마스의 악마들이 훔쳐 갔어요."] = "573851fae77cd06367281ad5d921bf9b",
        },
        [16114] = {
            ["은빛 여명회는 무능력한 이상주의자들에 불과해요. 하지만, 망상에 사로잡힌 그들의 지도자는 자기들이 뛰어나다고 생각하고 있답니다. 저는 붉은십자군의 사절로 이곳에 파견되었습니다. $r의 사절이여, 당신이… 켈투자드의 군대에 약간의 타격이라도 줄 수 있을지 의문이군요. 우리가 힘을 합치든 그렇지 않든 말입니다. 하지만, 기적이 일어날 때까지 그들의 공격을 방어하는 정도는 할 수 있을 거예요.$B$B저요? 저는 전쟁터에서 죽을 각오가 되어 있어요…$B$B<어깨를 으쓱하는 마잔>"] = "7dde9ae82fc3dac0e978a835607357c8",
        },
        [16115] = {
            ["구원의 갑옷은 우리 중 가장 신앙심이 깊었던 기사가 사용했던 것이오. 그걸 입을 자격이 있었던 것은 빛의 수호자 바로 그였소!$B$B마지막 전쟁에서 수천 명이 전사했지. 그들의 시체에서 벗겨진 방어구들은 공포의 요새 낙스라마스로 운반되었소.$B$B낙스라마스에 있는 죽음의 기사들이 어떤 목적에 사용하기 위해 구원의 갑옷을 더럽히고 있다는 얘기를 들었소.$B$B어찌 이런 비극이 있을 수 있단 말인가..."] = "413977ef54e229a5943c4a37c970e4e7",
            ["조심하시오, $r|1이여;여;. 우리 빛의 결사단은 세계에 해악을 끼치는 자를 심판할 때 다른 형제들만큼 자비롭지 않소.$B$B코팩스를 분노케 하는 자들은 화를 면치 못할 것이오.$B$B내 형제들에게 볼 일이 없다면 우리가 모임을 계속할 수 있게 그만 가주시면 좋겠소."] = "ab082a0dacce89f2423a85518fe46a16",
        },
        [16116] = {
            ["<고개를 끄덕이는 안젤라>$B$B그들의 죽음 이후 여섯 대마법사는 절대 뚫을 수 없는 마법 장벽 뒤에 지팡이를 봉인하고 감시자를 두는 것이 가장 좋은 방법이라고 결정했어요. 지팡이를 지키는 수호자 말이에요... 제가 바로 그 감시자였답니다."] = "c713a20e41938c73763a6be364694b66",
            ["계속해서 비극적인 사건이 일어났어요. 아티쉬와 접촉한 키린 토의 모든 마법사가 죽게 된 거죠.$B$B그러니까 아티쉬는 지각이 있는 물건이었어요. 살게라스가 부여한 것이죠..."] = "260835e952147cbb7a876af4c9aa6cac",
            ["그는 에이그윈님의 후손으로 티리스팔의 마지막 수호자였습니다. 메디브 말입니다."] = "93c3d0734d2464cd5730f70b6d5bebdd",
            ["달라란이 멸망한 후 저는 키린 토를 떠났어요. 아티쉬를 수호하면서 수년을 보냈지만 키린 토에서 제게 맡긴 중요한 임무가 한순간에 무너졌지요. 평생이 걸린다 해도 그 지팡이를 찾고 말 거예요. 제가 은빛 여명회에 합류한 것도, 여기 온 것도 바로 그 때문이에요."] = "e31f9aa725b12b20135051ca058312a9",
            ["쓰러진 티탄의 타락, 파괴자의 타락을 뜻하는 겁니다. 결국, 그 지팡이는 증오의 씨앗으로부터 탄생한 것이죠. 제가 여기 온 것도 바로 그 때문이고..."] = "28cf85bb2ada6ed1f79286dd08cc5e99",
            ["아주 좋은 질문이군요.$B$B경치 좋은 야외에서 사냥하는 게 좋다면 역병지대, 아즈샤라, 불타는 평원, 악령의 숲, 실리더스, 여명의 설원에서 정령의 정수를 찾을 수 있어요. 아, 운고로 분화구도요.$B$B위험을 즐기는 편이라면 혈투의 전장으로 가보세요. 그곳에서 다양한 정령의 정수를 아주 많이 찾을 수 있다는 얘기를 들었답니다. 검은바위 나락의 검은무쇠단 드워프들이 캐고 있는 정수를 찾아보셔도 좋을 거예요."] = "2ab19e8f4975368b71069106f4f9e703",
            ["이야기가 거의 끝나갑니다. 달라란은 아키몬드에 의해 거의 파괴됐고 지팡이는 사라졌어요. 아마도 방벽의 안전장치에 의해 부서진 것 같아요.$B$B어떤 이들은 그 지팡이가 아키몬드의 복수를 불러온 원인이라고 믿고 있답니다."] = "24abd0790e880086be8e9845c402ee7c",
            ["저는 부서진 지팡이의 조각을 찾기 위해 아제로스 전역을 뒤지고 다녔어요. 그러던 중 지팡이를 다시 복원하려는 켈투자드의 계획을 알아냈지요. 그는 이미 지팡이 조각을 여러 개 모았습니다. 그가 가장 신뢰하는 부관들이 그 조각들을 보관하고 있어요.$B$B켈투자드의 손에 수호자의 지팡이가 들어가지 못하도록 막는 일은 너무나도 중요해요. 솔직히, 전 세계에 재앙이 일어나는 것은 물론이고 어떤 결과가 발생할지 저도 잘 모르겠습니다."] = "cbfe4959c0dccd84f4f0f7ec31d8ebe2",
            ["전설 속의 이야기죠. 되풀이해서 말할 시간도 없고 그러고 싶지도 않네요. 메디브가 마지막 수호자였다는 사실만 알아두세요. 수호자의 지팡이가 그의 힘과 타락의 근원이었답니다."] = "8a3e84c175ab25c48b49ca17b0135721",
            ["카라잔이 멸망한 후 키린 토에서는 한 무리의 마법사를 보내 탑을 조사하고 그곳으로 반입된 모든 물건을 빼앗었어요... 연구를 핑계로 말이죠. 전설의 지팡이가 발견되어 달라란으로 옮겨진 것이 바로 그때였어요."] = "6122d26d8170dc3ccd4b9e61fb944a4a",
            ["켈투자드가 수호자의 지팡이인 전설의 아티쉬를 찾고 있다고 합니다.$B$B그렇습니다, 메디브가 지니고 있던 바로 그 지팡이랍니다."] = "971c7add47ebb151a9436fa9054b5e73",
            ["켈투자드와 마찬가지로 저 역시 한때 키린 토의 마법사였죠. 그리고 켈투자드처럼 수호자의 지팡이인 전설의 아티쉬를 찾아다녔지요. $c|1이여;여;, 우리 운명은 그렇게 얽혀 있답니다."] = "2e1a14887634a9235eb8a2b52a40e043",
        },
        [16123] = {
            ["잘못한 투자에 대해 얘기해 보게!$B$B발타라크 군주의 암흑 마법책은 벌써 암시장에서 고가에 팔렸다고. 그런데 그는 자기 물건이 도난당했다는 사실을 순순히 받아들이지 않았지. 그 나쁜 녀석은 벌써 몇 달 전에 죽었으면서 아직도 우리를 괴롭히고 있다네!"] = "7851f71608300be24d2a60246c177a38",
        },
        [16131] = {
            ["그렇소, 해골사신의 갑옷 말이오. 일전에 말했다시피 우리 중창단의 테너였던 돈 훌리오라는 고집쟁이 친구가 모든 것을 가르쳐 주었소이다. 그는 로데론 전역을 여행하며 흥미로운 기술을 많이 익혔지. 그중 하나는 죽은 스컬지의 뼈를 취해서 아주 튼튼한 가죽 방어구를 만드는 것이었소. 암살자에게 완벽한 갑옷이라고 할 만한 그런 물건 말이외다."] = "d6ee820d31d12325db3bb0117d5ad5ed",
            ["바보요, 당신? 여기까지 오면서 뼈만 앙상한 해골들이 경관을 망치고 있는 꼴을 못 본 건 아니겠지?$B$B<한숨을 쉬는 로한>$B$B밖에서 활동하는 걸 좋아한다면 동서부 역병지대 전역에서 놈들을 찾을 수 있소. 날 믿으시오. 꼭 당신 눈에 띌 테니까. 놈들은 당신을 절대 놓치지 않으려 할 거요.$B$B던전을 좋아한다면 스트라솔름과 스칼로맨스로 가시오. 해골 조각을 찾기에 아주 좋은 장소요."] = "13a767725c325fa51d467e80639b5c7b",
            ["아, 내 호칭이 말해 주듯이 난 붉은십자군을 위해 일하는 암살자라오. 낮에는 제거 대상을 우선순위대로 암살하고 밤에는 가젯잔 무도회장에서 춤과 함께 시간을 보내지. 춤은 나의 진정한 꿈이라오. 암살은 단지 돈을 벌기 위한 수단일 뿐이고 말이오."] = "512f340d076023b4c9448a6a0aa5f962",
            ["아무래도 내 호칭이 잘못된 것 같소. 나도 알고 보면 참 좋은 사람인데 말이지..."] = "7d3224526057b707f3979b7b1671e479",
            ["어허, 참! 내 옆에 서 있는 저 친구만큼이나 정상이라오. 뭐, 좋을 대로 생각하시오. 하지만, 난 그 방어구를 만들 능력이 있는 사람이지. 원한다면 계약을 맺을 수도 있소이다. 어서 빨리 이 암살자 생활을 청산하고 싶단 말이오."] = "f58bd8742f434e11faf30ac0397cb63c",
            ["좋은 질문이군. 젊은 시절 난 세상 돌아가는 일엔 신경 쓰지 않고 자유분방하게 지냈었지. 그 당시 난 스톰윈드를 떠돌며 노래를 부르던 돈 사중창단에 있었소이다. 떠돌며 지내던 그 시절 그 곳에서 해골사신의 갑옷을 제작하는 법을 배웠소."] = "c5eeeaf1edcbad1bef6a552484b6b991",
            ["하하, 이걸 어쩌나? 그 무도회장은 회원 전용이오!"] = "e9681ae779f33089e0a1a4491af83568",
        },
        [16132] = {
            ["그 역겨운 짐승들은 어디에나 있습니다.$B$B야외에서 사냥하는 걸 즐긴다면 역병의 숲과 테러데일 근처에서 놈들을 찾아보십시오. 그리고 동부 역병지대에 있는 거의 모든 스컬지 야영지에도 놈들이 나타납니다.$B$B던전 탐험을 즐기는 편이라면 스트라솔름으로 가십시오. 지하마귀가 사는 지역을 찾을 수 있을 겁니다. 그리고 스칼로맨스에서도 다양한 종류의 소생한 지하마귀를 찾을 수 있을 겁니다."] = "86a91c29a823bc19ba74c174cebf69ae",
            ["붉은십자군에서는 대부분의 모임에 제 동생 록시를 보냈습니다. 하지만, 록시는 붉은십자군을 대표하기는커녕 자기 사냥개를 돌보는 일조차 할 줄 모르는 녀석이죠."] = "55bee4d94fe2ec071c1f49801c48e21a",
            ["저와 같은 직업을 가진 이들에게 지하마귀의 사냥 실력은 언제나 연구 대상이자 부러움의 대상이죠. 저는 이 땅에서 스컬지를 몰아내기 위해 그 짐승들을 수없이 해치웠습니다.$B$B제가 비록 지하마귀의 잔인성을 증오하기는 하지만 그 능력만큼은 대단하다고 인정합니다. 사실 그들은 맡은 임무를 충실히 수행하는 것뿐이지요."] = "1bb2d36c1471ccc6854f72988e3b2362",
            ["지하마귀의 껍질과 다양한 신체 부위를 활용할 방법을 발견했습니다. 지하마귀의 껍질을 낙스라마스에서 사라진 더럽혀진 마법의 방어구에 결합하면 아주 가벼우면서도 엄청난 힘을 지닌 방어구 세트를 만들 수 있단 말입니다."] = "c3277c86a4fa82a1bddd12127f42cee9",
        },
        [16133] = {
            ["멍청한 녀석, 그건 힘이다.$B$B<노기를 띠고 째려보는 마타우스>$B$B예전의 영광을 되찾는 일에만 급급한 여기 바보들은 너같은 멍청이를 낙스라마스로 보낼 모양이야. 더럽혀진 그 갑옷을 되찾아 정화할 셈이겠지…$B$B<침을 뱉는 마타우스>$B$B그런 멍청한 생각을 하다니 참을 수가 없군.$B$B나 역시 그 갑옷을 찾아봤지만 아주 사악하고 더러운 상태였다."] = "c943281a6d8472a873a6c97a00f1de85",
            ["애송이 녀석, 나는 허세 따위는 부리지 않는다. 그런 암흑의 갑옷을 지니고 있으면 우리 둘을 해치우는 건 일도 아니란 말이지. 가격이 아주 비싼 것도 바로 이 때문이다. 만약 내가 죽어 대신 갑옷을 차지하는 녀석은 아주 부자가 되겠지.$B$B사실, 네가 어떻게 죽든지 놀의 침 방울만한 눈물도 흘리지 않을 테지만, 시키는 대로만 해! 내가 말하는 재료를 가지고 와라. 그럼 우리 모두 이득을 보게 되는 거야. 이미 말했다시피 불복종은 곧 죽음이다..."] = "c3138924933336621f5295591b7152ae",
            ["원하는 게 뭔가? 왜 나를 분노의 마타우스라고 부르는지 두 눈으로 확인하고 싶지 않으면 어서 사라져!"] = "46c26045969305b4f1afa87dc761ac0c",
        },
        [16134] = {
            ["그 당시 난 막 사춘기에 접어든 어린 타우렌이었지. 하지만, 내 이름을 걸고 만든 방어구가 자유를 위하여 전쟁에 뛰어든 용감한 이들을 든든하게 지켜줄 것을 알고 있었소."] = "102e0b4ad57167106f63887340efcdd5",
            ["오, 만나고 싶었...$B$B<콜록거리는 림블랫>$B$B아, 미안하오. 오래된 지병이라서 말이오. 내 소개를 하리다. 난 속세의 고리회의 림블랫이라 하오."] = "2c121d996480b972ca128fe4dd17568b",
            ["우리 가문은 수백 년 동안 오염된 대지를 회복하기 위해 노력해 왔소. 나도 아버지와 할아버지처럼 대지의 힘을 이용해 방어구를 만들 수 있는 기술을 물려받았지."] = "261c833a674804c528c3991040fe6265",
            ["우리 타우렌족은 마지막 전쟁에 참가했소. 스컬지의 침공으로부터 이 세계를 지키기 위해 주술사들이 투입되었지. 대부분 목숨을 잃었소이다. 살아남은 타우렌들도 그 저주받은 요새로 끌려가 사악한 실험에 이용됐소. 온몸이 갈가리 찢기다가... 그들의 죽음이 너무나 애통하지만 그 용기를 생각하면 내 가슴이 벅차오르는구려."] = "65e7b100fb21e8d6d72f6a72a8e28b8f",
        },
        [16135] = {
            ["밖에서 사냥을 즐기는 편이라면 악령의 숲에 사는 나무정령과 운고로 분화구의 덩굴손에게서 야생 잎사귀를 찾는 것이 좋습니다.$B$B좀 더 위험을 즐기는 편이라면 혈투의 전장으로 가십시오. 그곳 동쪽과 서쪽 전당은 거의 무한한 야생 잎사귀의 보고이니까요."] = "ca612f9695245d53b26272938714b047",
            ["엘룬께 영광을! $c님, 림블랫과 대화하던 중이라 오시는 걸 못 봤군요. 죄송합니다. 림블랫은 이 땅도 충분히 되살릴 수 있다고 믿고 있답니다."] = "f7cb5d818b4259306750c7395a10a00f",
            ["우리는 저마다 다른 사연으로 여기 왔어요.$B$B<미소를 짓는 레이네>$B$B저는 속세의 고리회의 림블랫을 만나러 왔습니다. 그는 이 땅을 정화하는 방법에 대한 흥미로운 이론을 알고 있어요."] = "32fb9a5f34cae334b11ddc1ef3aaafda",
            ["저는 명성이 자자한 물건을 만드는 장인이에요. 필요한 재료만 있으면 꿈의감시자 의복을 만들 수 있어요. 드루이드, 심지어 일부 주술사조차 이 갑옷의 마력에 강하게 끌린다고 합니다. 어때요, 관심 있으세요?"] = "182a2f807168b02644f4daff8caa6b4b",
            ["제 생각은 좀 달라요. 림블랫은 이 죽은 대지에서도 새 생명이 자랄 수 있다는 걸 증명했어요. 이제 새롭게 피어난 생명을 꾸준히 성장시키는 방법을 찾는 것이 더욱 중요합니다.$B$B그리고 여기 있는 동안, 전 낙스라마스로 가는 모험가들을 돕고 있어요."] = "2c8bea531a145f78fd5e857b6b8fabd4",
        },
        [16212] = {
            ["난 당신과 '냄새 알아맞히기' 놀이나 하고 있을 시간이 없소. 용건을 말하든가 아니면 내 눈앞에서 사라져 주시오!"] = "b5c51729cbfc4944277ef2a9a1158a7e",
        },
        [16226] = {
            ["칼을 겁내지 말게나. 하나도 위험하지 않으니까!"] = "aa468b41ee1967bb79c4f9ff0c0d575f",
        },
        [16227] = {
            ["어디로 날아가고 싶습니까?"] = "8d5a94fecd48af8f93d9d75d365ea743",
        },
        [16230] = {
            ["이 이교도들은 제정신이 아니로군..."] = "73f0462573697c404b28308bec6f882a",
        },
        [16254] = {
            ["<투덜거리는 야전사령관 챔버스>$B$B이곳까지 보급품을 무사히 수송하도록 디디어를 도와주었다는 애송이가 바로 당신이오? 나머지 사람들은 어디 있소? 더 많은 걸로 알고 있는데... 당신 같은 애송이들은 보통 무리를 지어 몰려다니더군.$B$B흥, 서명은 해줄 테니 확인서나 이리 주시오."] = "51a682137b7a6db94a26971a20130651",
        },
        [16256] = {
            ["1천여 년 전에 아탈라이라고 알려진 트롤 사제 집단이 영혼의 약탈자 학카르라고 하는 고대 혈신을 깨우려고 했습니다. 그로 인한 내란에서 패배한 사제들은 슬픔의 늪으로 유배되었고, 그들은 그곳에서 학카르를 위한 신전을 지어 바치고 그를 물리적인 이 세계로의 현신을 준비했습니다. 아탈라이의 계획을 곧 알아낸 용의 위상 이세라는 그 신전을 늪 아래로 처박아 버렸고 오늘날까지 그 신전의 폐허는 강력한 녹색용들이 지키고 있습니다."] = "7dc247370c0f46388922e4ad2824f973",
            ["가라앉은 사원은 슬픔의 늪 동쪽에 있는 거대한 호수 한가운데에서 찾을 수 있습니다."] = "75ed2903e0af8abe0c91025f4d1a631e",
            ["가시덩굴 구릉은 불모의 땅 남단, 길 동쪽에 있습니다."] = "ae45cd449d9b601c1faa2ad7d470e04a",
            ["가시덩굴 우리는 불모의 땅 남단, 길 서쪽에 있습니다."] = "4855c8dab63ff7e92429d6df87b7b3cd",
            ["가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다."] = "ae6bac71d95fa9cc576583cb12b00b0a",
            ["검은바위 산은 이글거리는 협곡을 북쪽에, 불타는 평원을 남쪽에 두고 그 사이에 있습니다."] = "7beb3ee244d9c85c277537d4ba4a2fe1",
            ["검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠단 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다."] = "3644fa36f35ecdc5947046c71b54837a",
            ["검은심연의 나락은 잿빛 골짜기 해안을 따라 가면 있는 조람 해안 북쪽 끝에서 찾을 수 있습니다."] = "2d41c6e84da0f60aa520a4acc8919f87",
            ["고대의 전쟁 동안, 반신 아감마간은 불타는 군단과 싸우기 위해 나섰습니다. 그 거대한 멧돼지는 패배했고 그가 피를 흘린 자리에서는 시간이 지나자 가시 돋친 덩굴이 자라났지요. 이 지역을 점령한 가시멧돼지들은 이곳을 성지로 받들고 있습니다. 이 거대한 가시덩굴 지역의 중심부에 바로 가시덩굴 우리가 있답니다. 가시덩굴 우리는 서슬깃 차를가라는 노파가 점령했는데, 혹자들은 그 노파가 어떤 교활한 목적을 위해 스컬지 요원들과 내통을 하고 있다고 추측하고 있습니다."] = "13d77ffe00e095b4ad42eef5a8aaebfb",
            ["그림자송곳니 성채는 은빛소나무 숲 남쪽, 장작나무 마을 바로 북쪽에 있습니다."] = "17d13be0366794572061fb3fbb409ee6",
            ["놈리건은 던 모로 서쪽에 있습니다."] = "1e16c8ae0545b101ebc5ad4d9c69c248",
            ["달라란 마법사들이 3차 대전쟁 중 언데드에 대한 조치가 제대로 진척되지 않자, 이에 실망한 대마법사 아루갈은 자기 편의 줄어드는 군세를 보충하기 위해 전혀 다른 차원에서 늑대인간들을 소환하기로 결정했습니다. 이 늑대인간들은 스컬지를 참살한 후 곧 마법사들에게 반기를 들었고 실버레인 남작의 성채를 포위했지요. 이 요새는 빠르게 암흑과 폐허로 무너져 갔고 죄책감에 미쳐 버린 아루갈은 늑대인간들을 자신의 후예로 삼아 '그림자송곳니 성채'라는 새로운 이름으로 불리게 된 그 요새로 퇴각했습니다."] = "b69ededa6dbdfe26a15fda5121e90a20",
            ["던 모로에 위치한 놈리건은 최근 돌연 변이 트로그들이 출몰하고는 있지만 아주 오랜 세월 동안 노움들의 수도였습니다. 보복을 위해 필사적으로 노력하던 땜장이왕 멕카토크는 놈리건의 방사성 폐기물 탱크의 비상 배출을 명령했지요. 트로그들은 방사선에 노출되었지만, 그들의 공성 기세는 약화하지 않았고 노움들은 드워프족의 도시 아이언포지로 피신할 수밖에 없었습니다. 땜장이왕은 이제 아이언포지에서 자신들의 사랑하는 수도를 되찾는 일을 도와 줄 용기 있는 자들을 모집하고 있습니다."] = "6cc5772934f51d4bcf44e66f9cb19266",
            ["마라우돈은 뾰족바위 골짜기에 있는 잊혀진 땅 서쪽 해안의 중간 지점에 있습니다."] = "b32b2b77a0839ff8c1415be4d2623dd9",
            ["마라우돈은 잊혀진 땅에서 가장 성스러운 곳 중 하나입니다. 이 거대한 신전 겸 동굴은 반신 세나리우스가 낳은 두 명의 불멸의 아들 중 하나인 재타르의 묘소이지요. 전설에 의하면, 재타르와 대지 정령 공주 테라드라스가 사생인 켄타우로스 종족을 자신들의 자식으로 삼기로 했고, 그들이 나타나자 야만적인 켄타우로스족은 자신들의 아버지에게 반기를 들어 그를 죽였다고 합니다. 어떤 이들은 테라드라스가 슬픔을 못 이겨 재타르의 영혼을 그 굽이치는 동굴 안에 가두고 그 힘을 어떤 사악한 목적으로 이용했다고 믿습니다."] = "44f65d16974643e3b29f727a67787ad0",
            ["모험가여, 희망의 빛 예배당에 오신 것을 환영합니다."] = "62d77d311ff95b739586b58c132d853b",
            ["붉은십자군 수도원은 티리스팔 숲 북동쪽에 있는 언덕에 있습니다."] = "fe604977d24d31743e5481d5dcda2e88",
            ["사랑의 징표는 도시와 마을에서 사랑을 찾는 시민들에게 줄 수 있어요. 답례로 애정이 담긴 선물을 받을 수 있을 거예요.$B$B손님께서 벌써 사랑을 받으셨다면 최소한 우정의 징표라도 줄 거랍니다."] = "cd40129110d4c4917a537fef57180329",
            ["성난불길 협곡은 오그리마 중심부에 있는 어둠의 틈 바로 밑에 있습니다."] = "b960d46bc6e1afd8a8048e75631efeb5",
            ["성난불길 협곡은 오그리마의 어둠의 틈 밑에 서로 연결된 화산 굴들로 구성되어 있습니다. 최근 사악한 어둠의 의회를 섬기는 이교집단이 이 협곡의 타오르는 심연 내에 자리를 잡았다는 소문이 퍼졌지요. 불타는 칼날단이라 알려진 이 이교집단은 듀로타의 주권 자체를 위협하고 있습니다. 많은 이들이 오크 대족장 스랄이 불타는 칼날단의 존재를 알고 있지만 이들이 어둠의 의회로 자신을 인도할 수 있을 거라는 희망때문에 그들을 멸하지 않기로 했다고 믿고 있습니다."] = "4a0636d96305a16097c01ed6971f7971",
            ["수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다."] = "2da51ca0be53ce695776bbe3e3eea8c7",
            ["스칼로맨스는 카엘 다로우 요새 아래에 있는 납골당에 있습니다. 한때 바로브 귀족 가문이 소유하던 그 요새는 2차 대전쟁 후 폐허가 되어 버렸지요. 마법사 켈투자드는 그의 저주받은 자들의 교단에 입단할 추종자들을 모집하면서 종종 리치 왕을 섬기는 자들에게 불멸의 생명을 약속하곤 했는데, 바로브 가문도 그의 영향력에 빠져 자신들의 요새를 내놓았지만 이교도들은 그 가족을 살해하고 납골당을 강령술 학교로 만들어 버렸습니다. 켈투자드는 더 이상 그곳에 있지 않지만 이교도들과 교사들은 아직도 남아 있습니다."] = "44fdd52098e4ecaeddc946e101d7c60f",
            ["스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다."] = "4414ebedf67147d4801e58071b11c237",
            ["스톰윈드 지하감옥은 스톰윈드의 마법사 지구 근처에 있습니다."] = "8b063ee787233090be02c8d7fc8e58a7",
            ["아니에요, 전 아니지만 많은 이들이 사랑을 갈구하고 있답니다. 손님께서는 제가 팔고 있는 사랑의 징표를 구입하시고 은은한 향수나 매혹적인 향수를 뿌린 후 다른 이들을 스쳐 지나가며 매력을 풍기셔야 하죠!"] = "54899ff43d9fa3680bd5231fd54eae44",
            ["울다만은 세계 창조 이래로 땅속에 묻혀 있던 고대 티탄의 저장고입니다. 드워프의 발굴로 인해 티탄의 첫 번째 창조 실패작인 트로그들이 최근에 풀려났습니다. 전설에 의하면, 티탄들이 트로그 실험을 실패로 간주하고 다시 시도를 했을 때 드워프 종족이 탄생한 것이라고 합니다. 이 비밀은 저 전설적인 노르간논의 원반에 기록되어 있습니다. 이 어마어마한 크기의 유물은 고대 도시 울다만의 바닥에 있는데, 살아 있는 거대한 바위 피조물이 보호하고 있답니다."] = "a25c5d7842af31618a063b3d3ce15fed",
            ["울다만은 황야의 땅 북쪽 맨 끝에 있습니다."] = "4324821d63a3f73937dd5abffe6fdf7f",
            ["은은한 향수나 매혹적인 향수를 뿌리면 누가 사랑을 찾고 있는지 알게 되실 거예요. 그들은 사랑의 징표를 받고... 답례로 선물을 주지요.$B$B하지만, 누군가에게 사랑의 징표를 주려면 적당한 향기를 풍겨야 해요! 여자들이 은은한 향수를 좋아하는 한편 남자들은 매혹적인 향수를 좋아하거든요."] = "8e4dcb74091e2e615d506f3ec7d147ca",
            ["이 던전들 중 하나를 골라 탐험해 보시겠습니까?"] = "9211a5a83384bc6bf667f9e87661f2b5",
            ["이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 볼바르님, 마그니님, 그리고 티란데님 곁에서 찾을 수 있을 거예요."] = "0838f3fe0e3c17a16a7ff7d504eec929",
            ["이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 케른님, 실바나스님, 그리고 스랄님 곁에서 찾을 수 있을 겁니다."] = "9f470e7a9c62fa04faeb58fd3b1d6de9",
            ["잿빛 골짜기의 조람 해안에 위치한 검은심연의 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남아 있었는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다."] = "639f5e4137099522e1302487ff27f679",
            ["죽음의 폐광은 서부 몰락지대 남쪽에 있는 문브룩 아래에 있습니다."] = "cce75935af7718f82fcb4c3d13f23020",
            ["줄파락의 폐허는 타나리스 사막의 북서쪽 가장자리에 있습니다."] = "5521f2e5d2e37d7012ea87b75badcb01",
            ["지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다."] = "9f8d7c84b3cbfc322f53a0a242de804e",
            ["최근에 나랄렉스라고 하는 나이트 엘프 드루이드가 불모의 땅 중심부에 있는 지하 동굴을 발견했습니다. 그 동굴의 샘을 이용해 불모의 땅을 다시 푸르게 만들 수 있을 거라 생각한 나랄렉스는 그 유명한 에메랄드의 꿈의 마력을 끌어들이기 시작했지요. 하지만 그의 예견은 어떻게 돼선지 악몽으로 변해 버렸고 통곡의 동굴은 곧 사납고 무서운 짐승들의 소굴이 되어 버렸습니다. 들리는 바에 의하면 그 미궁 안 어딘가에서 여전히 나랄렉스가 에메랄드의 꿈 가장자리 너머에 갇혀 살고 있다고 합니다."] = "4d1835c423b0ee4a6773a1481ea2d03e",
            ["통곡의 동굴 입구는 불모의 땅에 있는 교차로에서 남서쪽으로 가면 찾을 수 있는 푸른 오아시스에 있습니다."] = "58d9f5adb0c15d9e359abb8b40a54a91",
            ["폐허가 된 도시 스트라솔름은 역병의 숲 북쪽에 있는 동부 역병지대에 있습니다."] = "d9516bdeb534c80940a3be1f4600bf04",
            ["한 나이트 엘프 마술사의 비밀 분파가 1만 2천 년 전에 지은 고대 도시 엘드레탈라스는 아즈샤라 여왕이 가장 소중히 여기는 마법 비밀을 보호하는 데 사용되었습니다. 세계의 분리로 인해 파괴되기는 했지만 불가사의한 이 도시의 상당 부분이 혈투의 전장이라는 이름을 지니고 으리으리한 모습으로 여전히 남아 있답니다. 서로 뚜렷이 구분되는 이 폐허의 세 지구에는 온갖 종류의 생물들이 출몰하고 있는데, 특히 명가의 유령들이나 사악한 사티로스, 그리고 포악한 오우거들이 많이 나타나고 있습니다."] = "97a393e1ef12dc1fe4a4b55e63c2c620",
            ["한때 검은무쇠단 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다."] = "e4835262a6e71a36692d90aedbb66c42",
            ["한때 북부 로데론의 보석이라 불리던 스트라솔름은 바로 아서스 왕자가 자신의 스승인 빛의 수호자 우서 경을 배반하고 언데드 역병에 걸린 것으로 간주된 자신의 수백 명의 백성을 살해한 곳입니다. 그 후 아서스는 곧 리치 왕에게 항복했지요. 현재 이 파괴된 도시에는 강력한 리치 켈투자드가 이끄는 언데드 스컬지와 십자군사령관 다스로한이 이끄는 붉은십자군 파견대가 거처하고 있으며, 이 두 진영은 끊임없이 격렬한 전투를 치르고 있습니다."] = "4bcf2a35fd98e48b3cd346ec97dccde8",
            ["한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 문브룩 마을에 있다고 하더군요."] = "e118425d7cca455fae7064446900535b",
            ["햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래부족 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다."] = "0f7f53045dc845e1ab759203cc598d30",
            ["혈투의 전장의 폐허는 페랄라스 중심부에에 있습니다."] = "863a0466292f35423e25fb6b1e18e872",
        },
        [16283] = {
            ["여기 이 짐말들은 하루에 두 번 나간다네. 그런데, 스컬지가 길을 비켜주지 않아 디디어와 노새들이 최전선에 보급품을 수송하지 못하면 난 끝장일세. 이렇게 환장할 노릇은 처음이군. 보급품 수송을 안전하게 지켜줄 영웅이 있다면 얼마나 좋겠나..."] = "b4e6217834a34f95034b22e071d3a451",
        },
        [16284] = {
            ["제발 좀 비켜 주십시오! 시간은 부족한데 할 일은 산더미 같아서요."] = "f21ac82310364bee548aaa65db9ae740",
            ["좀 비켜주시겠어요? 할 일은 태산인데 시간은 없단 말입니다!$B$B진흙구더기나 부패병에 감염된 분이라면, 제가 도울 수 있을 것 같군요."] = "69087ca98832c4d531ebd24380d184e3",
        },
        [16376] = {
            ["어느 날 밤 거장 오마리온이 홀연히 사라졌네. 마치 바람에 실린 방귀처럼... 휙 하고 사라졌지! 흥, 이제 최전선의 병사들에게 필요한 물건을 만들어 줄 수 있는 건 이 몸밖에 없단 말일세."] = "9cb182e6099250bd1e21445a5a8a786a",
        },
        [16381] = {
            ["<심각한 부상을 입은 타르시스>"] = "f9da3b9d9bfb527b32aa364ef806b9b5",
        },
        [16384] = {
            ["스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."] = "0973188afdf5745ee7a53c42da926c63",
            ["전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."] = "4d4e9052d3c36392e6211cb442ea3b1e",
            ["전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."] = "ebde1b78097e360ae80271b45ac8ec9b",
        },
        [16395] = {
            ["스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."] = "b4933008c7c76fbea261d6b6ba7192ca",
            ["전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."] = "fdaab9e2b8a9ef75ee889a83109b9758",
            ["전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."] = "4b36cae8ffab10bd243caafa37fd7ebd",
        },
        [16399] = {
            ["비켜, 이 비열한 놈아! 레빌가즈가 교수형은 면하게 해줬지만 아마도 난 그에 못지않은 끔찍한 벌을 받게 될 것 같단 말이야."] = "1fad4f6979d035d1a0174cea5dd2b07c",
        },
        [16416] = {
            ["무슨 일로 오셨나요, $n? 어서 말씀해 보세요. 전 그리 한가하지 않아서요!"] = "b9dfff243575891bcfc18fc60feb4f58",
        },
        [16417] = {
            ["뭘 도와 드릴까요? 아니, 잠깐! 제게는 뭘 해 주실 수 있죠?"] = "b89ae8e419d78a1676fef5d680e3b072",
        },
        [16418] = {
            ["문제를 일으키지 않는 게 좋을 텐데요, $N씨!"] = "5aefa54174f6577b8f87afc692df3764",
        },
        [16433] = {
            ["스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."] = "b4933008c7c76fbea261d6b6ba7192ca",
            ["전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."] = "fdaab9e2b8a9ef75ee889a83109b9758",
            ["전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."] = "4b36cae8ffab10bd243caafa37fd7ebd",
        },
        [16434] = {
            ["스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."] = "b4933008c7c76fbea261d6b6ba7192ca",
            ["전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."] = "fdaab9e2b8a9ef75ee889a83109b9758",
            ["전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."] = "4b36cae8ffab10bd243caafa37fd7ebd",
        },
        [16435] = {
            ["스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."] = "0973188afdf5745ee7a53c42da926c63",
            ["전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."] = "4d4e9052d3c36392e6211cb442ea3b1e",
            ["전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."] = "ebde1b78097e360ae80271b45ac8ec9b",
        },
        [16436] = {
            ["스컬지를 상대로 한 싸움의 첫 단계가 성공적으로 진행되고 있습니다. 우리는 이미 몇 번의 성공을 거두었습니다. 저의 지원으로 앞으로 전투에서도 승리를 가져오기를 바랍니다."] = "0973188afdf5745ee7a53c42da926c63",
            ["전투는 아주 성공적이며 스컬지 세력이 약해진 것 같습니다. 우리 해안에서 스컬지를 몰아내는 것은 이제 시간문제일 뿐입니다. 이 전투에 도움이 되도록 당신에게 마법을 걸어 드리겠습니다."] = "4d4e9052d3c36392e6211cb442ea3b1e",
            ["전투에서 승리했습니다! 스컬지의 침공은 당분간 주춤할 것입니다. 고마움을 표시하고 앞일을 대비하는 의미에서 우리가 가진 것을 나눠 드리겠습니다."] = "ebde1b78097e360ae80271b45ac8ec9b",
        },
        [16439] = {
            ["<겉옷을 들어올려 상처투성이인 몸을 보여 주는 종교재판관 페어뱅크스>$B$B그렇소, 나도 거기에 있었소. 난 대영주께서 가장 신뢰하는 참모였소. 내가 그때 알아차렸더라면... 지금도 그때 일을 생각하면 내가 큰 실수를 저지른 탓인 것만 같소. 거기에 스컬지들이 수천도 더 매복해 있었다면 믿겠소?"] = "24440986d066c412e745cb3c6ce760e7",
            ["<고개를 끄덕이는 종교재판관 페어뱅크스>$B$B그렇소. 붉은십자군 사령관으로 알려진 모그레인님의 아들이 한 짓이지. 내가 아는 바로는 십자군 사령관도 동일 인물이라오. 아버지를 적이 매복해 있는 장소로 유인한 사람이 다름 아닌 그 아들이었단 말이지."] = "e63237fcdb254837bb237bc6825c17a5",
            ["<고개를 젓는 종교재판관 페어뱅크스>$B$B아니오, $r! 그분의 아들 중 한 명만 죽었을 뿐이오. 한 명은 아직 살아 있지.$B$B<하늘을 가리키는 종교재판관 페어뱅크스>$B$B아웃랜드... 그곳으로 가서 그를 찾으시오."] = "ce325ed39a2037717fc38eab2e26d0c2",
            ["<고개를 젓는 종교재판관 페어뱅크스>$B$B아니오... 그저 멀찌감치 서서 언데드 군대가 우리에게 달려드는 걸 지켜보고만 있었지. 그리고 난 이내 완전히 지치고 말았소. 내가 먼저 쓰러졌지. 놈들은 의식을 잃은 나를 갈기갈기 찢어놓을 수도 있었지. 하지만 오로지 대영주님을 쓰러뜨리는 데만 혈안이 되어 있던 놈들은 내게 신경도 쓰지 않더군."] = "8d7b4c056646c2832e1e7a746024ce6e",
            ["그 한 사람이 파멸의 인도자라면 당연한 일이지, 이 멍청한 친구야! 스컬지들이 우리를 포위하자 모그레인님께서 검을 꺼내 들었고... 그의 아들은 바로 도망쳤지. 놈들은 여태껏 내가 한 번도 보지 못한 무서운 광기를 드러내며 우리에게 달려들었소. 그런데..."] = "86cb1182381c2163a7c4ab7156155f5c",
            ["그런 영웅이 죽는 이유는 단 한 가지밖에 없는 법이지, $r! 돌이킬 수 없는 비극. 그것뿐이라오. 십자군 사령관이란 자가 켈투자드와 은밀한 거래를 한 거요. 결국, 잠복해 있던 놈들에게 습격을 당해 모그레인님은 세상을 떠나시고 말았지. 가장 믿고 아끼는 자의 배신이 아니었다면 이런 끔찍한 결과는 절대 일어나지 않았을 거요."] = "e76f6d578d1d69badcdc2108981f62c6",
            ["그렇소, 대영주 모그레인... 붉은십자군의 창설자이자, 고결한 성품과 신념을 지닌 기사였지. 아들에게 배신당해 스트라솔름에서 켈투자드의 군대에 살해되셨소. 그래서 나도 여기까지 온 거고..."] = "4e974e3350b6c509820ed806a61f8cec",
            ["그분의 아들이 파멸의 인도자를 집어들더니 아버지의 등 뒤에서 심장을 향해 검을 찔러 넣은 거요. 그분의 마지막 한 마디는 영원히 잊히지 않을 거요. '무슨 짓을 한 거니, 르노? 네가 왜 이런 짓을?'"] = "0bf4d357057413dcf37deed59af81109",
            ["난 스컬지 시체 밑에서 죽은 척하며 있을 수밖에 없었소. 시체 밑에 깔려 있었던 난 암울한 어둠과 전투의 소리만 희미하게 느낄 뿐이었소. 검이 부딪히는 날카로운 쇳소리, 이빨을 가는 소리, 무언가 짓이기는 소리… 온통 소름끼치고 무시무시한 소리만 들려왔지. 그리고 얼마 후 갑자기 정적이 흐르더니 대영주님께서 날 부르는 소리가 들렸소. '페어뱅크스! 어디 있는가. 페어뱅크스? 대답해봐!' 그 순간 믿을 수 없는 일이 벌어졌소. 믿을 수 없는 배신의 음모가 그 실체를 드러낸 거요…"] = "158d60b9203e43bccb639a79ecf4f2e3",
            ["대영주께서는 붉은십자군에 없어서는 안 될 존재였소. 사람들은 리치 왕의 군대와 싸워서 혁혁한 공을 세운 그분을 칭송하며 파멸의 인도자라 불렀다오. 모그레인님은 오로지 검과 신념만으로 전장 한복판에 뛰어들어 홀로 언데드들을 섬멸하고는 상처 하나 없이 귀환하곤 하셨소. 아직 무슨 말인지 모르겠소? 죽음조차 그분을 두려워했단 말이오! 그 이름만으로도 적들은 두려움에 떨었지."] = "34d834195951120718233ac59ca051bb",
            ["모그레인님과 그분의 검은 한 몸과도 같소. 이해할 수 있겠소? 그 일로 인해 검에는 저주가 내렸고 모그레인도 켈투자드의 기사가 되어버렸지. 그때 난 살아남으면 반드시 이 극악무도한 범죄의 진상을 세상에 밝힌다고 맹세했소. 부패하여 온갖 전염병균이 득실거리는 스컬지 시체 밑에 꼬박 이틀 동안 깔려 있으면서 난 파괴된 도시를 벗어날 힘을 최대한 비축했소이다."] = "c33b8942ece004a1babd96520d730a93",
            ["붉은십자군은 고위사령관 아벤디스, 종교재판장 이실리엔, 그리고 대영주 모그레인에 의해 창설되었소. 당시에는 정의로운 조직이었지. 그때만 해도 당신이 본 그런 광기와 맹신은 찾아볼 수 없었소. 적어도 십자군 사령관이란 자가 나타나 타락의 늪으로 서서히 빠져들기 전까지는 말이오."] = "d0c148b2bcf78858f8c4f040c24d57a9",
            ["수천 명으로도 모그레인님을 상대하기엔 역부족이었소.$B$B<잠깐 웃었다가 생각에 잠기는 페어뱅크스>$B$B수천 명이 달려들었지만 모두 모그레인님의 손에 쓰러지고 말았지! 위대한 빛의 힘으로! 달려드는 족족 그분의 검에 쓰러져나갔소. 그 아비규환의 와중에 난 모그레인님의 아들이 먼 곳에서 지켜보고 있다는 걸 알게 되었소. 난 그에게 소리쳤지. '르노, 어서! 아버지를 도와야 하지 않는가!'"] = "0b956b0314a9b7ebc97b96dcc57c0bcb",
            ["아무래도 당신 손에 들려 있는 그 검은 구원받기엔 틀린 것 같소. 원한의 골이 너무 깊단 말이오. 하지만, 희망을 버리진 마시오, $c! 끝이 있으면 시작도 있는 법이오.$B$B더 없이 독실하고 신앙심이 깊은 그분의 아들을 찾으시오. 그가 타락한 고대의 검 없이도 파멸의 인도자를 새로 만들 수 있다는 소문이 있소."] = "cc78ae5837cb3e1bcfbafd68c4b35542",
            ["이제야 저주가 풀렸군. 고맙소. 당신은 우리의 영웅이오."] = "60139c1e8304893e783a877f2adadf63",
            ["전혀 아는 바가 없단 말이오? 당신 등에 짊어진 그 검은 원래 주인의 이름을 따라서 파멸의 인도자라고 알려졌소."] = "aff37574b814f55f881169f5208b9e95",
            ["탈출했지. 당황한 그분의 아들이 나를 보지 못한 덕분에 붉은십자군 수도원으로 돌아올 수 있었소. 수도원에 들어서자마자 난 비명에 가까운 소리를 질렀지. 내 말에 귀 기울이는 사람이라면 누구든지 붙잡고 진실을 알렸소. 놈들이 알면 목숨을 건질 수 없는 걸 알기에 붉은십자군의 어두운 비밀을 간직한 이곳으로 숨어들었소이다. 하지만, 당시에도 내 말에 귀를 기울이며 믿어 주는 사람들도 있었소. 그렇게 해서 은빛 여명회가 탄생한 것이오."] = "6cb2125ca53137b1fd6250d4a478ed69",
        },
        [16458] = {
            ["1천여 년 전에 아탈라이라고 알려진 트롤 사제 집단이 영혼의 약탈자 학카르라고 하는 고대 혈신을 깨우려고 했습니다. 그로 인한 내란에서 패배한 사제들은 슬픔의 늪으로 유배되었고, 그들은 그곳에서 학카르를 위한 신전을 지어 바치고 그를 물리적인 이 세계로의 현신을 준비했습니다. 아탈라이의 계획을 곧 알아낸 용의 위상 이세라는 그 신전을 늪 아래로 처박아 버렸고 오늘날까지 그 신전의 폐허는 강력한 녹색용들이 지키고 있습니다."] = "4b24ea6b391a2efd0be7d84cc947d159",
            ["가라앉은 사원은 슬픔의 늪 동쪽에 있는 거대한 호수 한가운데에서 찾을 수 있습니다."] = "e33d4e6573f24d17efcc2b0ecf76516d",
            ["가시덩굴 구릉은 불모의 땅 남단, 길 동쪽에 있습니다."] = "9cdbd4512dccbc458675c5216058ddcd",
            ["가시덩굴 우리는 불모의 땅 남단, 길 서쪽에 있습니다."] = "25a80704f18ee56676b132bdded0fe94",
            ["가시덩굴 우리처럼 가시덩굴이 우거진 가시덩굴 구릉은 가시멧돼지의 전통적인 수도였습니다. 가시 덩굴이 얼기설기 퍼진 이 미궁에는 가시멧돼지 귀족들의 충실한 군대는 물론 대사제들 즉, 죽음의 머리교 일족이 살고 있습니다. 최근 이 조잡한 은신처에 기분 나쁜 그림자가 드리워지고 있습니다. 혹한의 암네나르가 이끄는 언데드 스컬지 요원들이 가시멧돼지를 지배하고 그들의 가시 미궁을 언데드 군단의 요새로 만든 것입니다."] = "bbbb6f1884cdacec9af6cb67e3e1abd4",
            ["검은바위 산은 이글거리는 협곡을 북쪽에, 불타는 평원을 남쪽에 두고 그 사이에 있습니다."] = "aab40b74860886caa96dcfdaf979e180",
            ["검은바위 산의 불타는 내부를 깎아 만든 이 강대한 요새는 데스윙의 교활한 아들 네파리안이 첨탑의 상층을 점령하고 검은바위 산의 화산 심연에 있는 드워프들과 전쟁을 치르기 전까지는 수세기 동안 사악한 검은무쇠단 드워프들이 차지하고 있었습니다. 강력한 불의 정령 라그나로스가 이 드워프들을 이끌고 있다는 사실을 깨달은 네파리안은 그의 적들을 제압하고 검은바위 산 전체를 손아귀에 둘 것을 맹세했습니다."] = "8f57f5e81f55defd22e287d36b233496",
            ["검은심연의 나락은 잿빛 골짜기 해안을 따라 가면 있는 조람 해안 북쪽 끝에서 찾을 수 있습니다."] = "0e3148ee13bdc4aad5af84663b24d1ce",
            ["고대의 전쟁 동안, 반신 아감마간은 불타는 군단과 싸우기 위해 나섰습니다. 그 거대한 멧돼지는 패배했고 그가 피를 흘린 자리에서는 시간이 지나자 가시 돋친 덩굴이 자라났지요. 이 지역을 점령한 가시멧돼지들은 이곳을 성지로 받들고 있습니다. 이 거대한 가시덩굴 지역의 중심부에 바로 가시덩굴 우리가 있답니다. 가시덩굴 우리는 서슬깃 차를가라는 노파가 점령했는데, 혹자들은 그 노파가 어떤 교활한 목적을 위해 스컬지 요원들과 내통을 하고 있다고 추측하고 있습니다."] = "310fe6a22db0bf2928c1ff8e5c70cd20",
            ["그림자송곳니 성채는 은빛소나무 숲 남쪽, 장작나무 마을 바로 북쪽에 있습니다."] = "6f1db228470e4b9d299edd3c7168c063",
            ["놈리건은 던 모로 서쪽에 있습니다."] = "a4f613548f3f5a63415a978d891ce475",
            ["달라란 마법사들이 3차 대전쟁 중 언데드에 대한 조치가 제대로 진척되지 않자, 이에 실망한 대마법사 아루갈은 자기 편의 줄어드는 군세를 보충하기 위해 전혀 다른 차원에서 늑대인간들을 소환하기로 결정했습니다. 이 늑대인간들은 스컬지를 참살한 후 곧 마법사들에게 반기를 들었고 실버레인 남작의 성채를 포위했지요. 이 요새는 빠르게 암흑과 폐허로 무너져 갔고 죄책감에 미쳐 버린 아루갈은 늑대인간들을 자신의 후예로 삼아 '그림자송곳니 성채'라는 새로운 이름으로 불리게 된 그 요새로 퇴각했습니다."] = "5d076554d313584aa1c5611cf0129a23",
            ["던 모로에 위치한 놈리건은 최근 돌연 변이 트로그들이 출몰하고는 있지만 아주 오랜 세월 동안 노움들의 수도였습니다. 보복을 위해 필사적으로 노력하던 땜장이왕 멕카토크는 놈리건의 방사성 폐기물 탱크의 비상 배출을 명령했지요. 트로그들은 방사선에 노출되었지만, 그들의 공성 기세는 약화하지 않았고 노움들은 드워프족의 도시 아이언포지로 피신할 수밖에 없었습니다. 땜장이왕은 이제 아이언포지에서 자신들의 사랑하는 수도를 되찾는 일을 도와 줄 용기 있는 자들을 모집하고 있습니다."] = "90657c7dd9fc98c4960a8c613e7e0841",
            ["마라우돈은 뾰족바위 골짜기에 있는 잊혀진 땅 서쪽 해안의 중간 지점에 있습니다."] = "6679f691680afda8b76a2dd04f2e7144",
            ["마라우돈은 잊혀진 땅에서 가장 성스러운 곳 중 하나입니다. 이 거대한 신전 겸 동굴은 반신 세나리우스가 낳은 두 명의 불멸의 아들 중 하나인 재타르의 묘소이지요. 전설에 의하면, 재타르와 대지 정령 공주 테라드라스가 사생인 켄타우로스 종족을 자신들의 자식으로 삼기로 했고, 그들이 나타나자 야만적인 켄타우로스족은 자신들의 아버지에게 반기를 들어 그를 죽였다고 합니다. 어떤 이들은 테라드라스가 슬픔을 못 이겨 재타르의 영혼을 그 굽이치는 동굴 안에 가두고 그 힘을 어떤 사악한 목적으로 이용했다고 믿습니다."] = "1d59940e7ccbee60370a304b33835f99",
            ["붉은십자군 수도원은 티리스팔 숲 북동쪽에 있는 언덕에 있습니다."] = "78e6008fbf1d737dce7812540853511c",
            ["사랑의 징표는 도시와 마을에서 사랑을 찾는 시민들에게 줄 수 있어요. 답례로 애정이 담긴 선물을 받을 수 있을 거예요.$B$B손님께서 벌써 사랑을 받으셨다면 최소한 우정의 징표라도 줄 거랍니다."] = "edd64941f9ca57aeaac37f4c4e0fdf4d",
            ["성난불길 협곡은 오그리마 중심부에 있는 어둠의 틈 바로 밑에 있습니다."] = "7bef92afa79765ff95f06d3660786a79",
            ["성난불길 협곡은 오그리마의 어둠의 틈 밑에 서로 연결된 화산 굴들로 구성되어 있습니다. 최근 사악한 어둠의 의회를 섬기는 이교집단이 이 협곡의 타오르는 심연 내에 자리를 잡았다는 소문이 퍼졌지요. 불타는 칼날단이라 알려진 이 이교집단은 듀로타의 주권 자체를 위협하고 있습니다. 많은 이들이 오크 대족장 스랄이 불타는 칼날단의 존재를 알고 있지만 이들이 어둠의 의회로 자신을 인도할 수 있을 거라는 희망때문에 그들을 멸하지 않기로 했다고 믿고 있습니다."] = "530c2f46cebb57733cec5f86ad8383d3",
            ["손님의 얼굴과 영혼은 지치고 힘들어 보이는군요. 저희 여관에서 지친 몸을 편히 뉘이시고 꿈 속에서 엘룬께 조언을 구하시기 바랍니다."] = "88ed28bad52992326e81df54efce5146",
            ["수도원은 한때 학문과 계몽의 중심지였습니다. 3차 대전쟁 당시 언데드 스컬지가 봉기하자 이 평화로운 수도원은 광신적인 붉은십자군의 요새로 바뀌었습니다. 붉은십자군은 인간이 아니라면 동맹이나 소속에 관여치 않고 관용을 보이지 않습니다. 그들은 외부인이라면 누구나 잠재적인 언데드 역병 보균자로 보고 그들을 처치해야 한다고 믿습니다."] = "54bd2c1a937b1392327adbdf92ce5e6d",
            ["스칼로맨스는 카엘 다로우 요새 아래에 있는 납골당에 있습니다. 한때 바로브 귀족 가문이 소유하던 그 요새는 2차 대전쟁 후 폐허가 되어 버렸지요. 마법사 켈투자드는 그의 저주받은 자들의 교단에 입단할 추종자들을 모집하면서 종종 리치 왕을 섬기는 자들에게 불멸의 생명을 약속하곤 했는데, 바로브 가문도 그의 영향력에 빠져 자신들의 요새를 내놓았지만 이교도들은 그 가족을 살해하고 납골당을 강령술 학교로 만들어 버렸습니다. 켈투자드는 더 이상 그곳에 있지 않지만 이교도들과 교사들은 아직도 남아 있습니다."] = "03ee214820f246ccc4e751c56c822ace",
            ["스칼로맨스라고 알려진 강령술 학교는 서부 역병지대에 폐허가 된 섬 카엘 다로우에 있습니다."] = "7eddf733901dbca29a5a21752dd1ceb4",
            ["스톰윈드 지하감옥은 스톰윈드의 마법사 지구 근처에 있습니다."] = "8f49377bcf39a38a76d2cf7cbacbefb0",
            ["아니에요, 전 아니지만 많은 이들이 사랑을 갈구하고 있답니다. 손님께서는 제가 팔고 있는 사랑의 징표를 구입하시고 은은한 향수나 매혹적인 향수를 뿌린 후 다른 이들을 스쳐 지나가며 매력을 풍기셔야 하죠!"] = "3334d2c3be49af24ec80966cd3044afb",
            ["울다만은 세계 창조 이래로 땅속에 묻혀 있던 고대 티탄의 저장고입니다. 드워프의 발굴로 인해 티탄의 첫 번째 창조 실패작인 트로그들이 최근에 풀려났습니다. 전설에 의하면, 티탄들이 트로그 실험을 실패로 간주하고 다시 시도를 했을 때 드워프 종족이 탄생한 것이라고 합니다. 이 비밀은 저 전설적인 노르간논의 원반에 기록되어 있습니다. 이 어마어마한 크기의 유물은 고대 도시 울다만의 바닥에 있는데, 살아 있는 거대한 바위 피조물이 보호하고 있답니다."] = "cac489d41abedaef7c5d7041fd7492e3",
            ["울다만은 황야의 땅 북쪽 맨 끝에 있습니다."] = "36de161eff379c5060e7c2e31cdc975a",
            ["은은한 향수나 매혹적인 향수를 뿌리면 누가 사랑을 찾고 있는지 알게 되실 거예요. 그들은 사랑의 징표를 받고... 답례로 선물을 주지요.$B$B하지만, 누군가에게 사랑의 징표를 주려면 적당한 향기를 풍겨야 해요! 여자들이 은은한 향수를 좋아하는 한편 남자들은 매혹적인 향수를 좋아하거든요."] = "136e146f620b6e7197755a682b68ce84",
            ["이 던전들 중 하나를 골라 탐험해 보시겠습니까?"] = "f70c987e98c43a9ac4f1ef6eb271008a",
            ["이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 볼바르님, 마그니님, 그리고 티란데님 곁에서 찾을 수 있을 거예요."] = "b19764fa4b6d3a891fa5f750b3dd2517",
            ["이곳 시민들에게 사랑의 징표를 건네주면 답례로 다양한 선물을 받게 될 거예요. 그중 몇 가지는 손님께서 지니고 사용하고 싶어하실 테지만, 다른 것들은 한데 묶어서 당신이 좋아하는 영웅에게 바칠 수 있어요! 큐이피를 찾아서 선물세트를 주세요.$B$B큐이피는 케른님, 실바나스님, 그리고 스랄님 곁에서 찾을 수 있을 겁니다."] = "f9432ed28b2dabcd595eddb702af9ca1",
            ["잿빛 골짜기의 조람 해안에 위치한 검은심연의 나락은 한때 나이트 엘프들의 달의 여신 엘룬에게 바쳐진 영광스러운 신전이었다고 합니다. 하지만 세계의 분리로 인해 신전이 파괴되어 장막의 바다의 물결 아래로 가라앉아 버렸지요. 그곳에 그 모습 그대로 남아 있었는데, 나가와 사티로스가 그 고대 마력에 이끌려 등장하더니 신전의 비밀을 캐내기 시작했습니다. 전설에 의하면, 고대 괴물 아쿠마이가 그 신전의 폐허 안에 자리 잡고 있다고 합니다."] = "f3dc300ddc1883b724afefb742b27c54",
            ["죽음의 폐광은 서부 몰락지대 남쪽에 있는 문브룩 아래에 있습니다."] = "c14eefa9bf01ea21ee6c512a62f5270c",
            ["줄파락의 폐허는 타나리스 사막의 북서쪽 가장자리에 있습니다."] = "927f2bfc50de1f03c38ac6ec3198f4a7",
            ["지하감옥은 스톰윈드의 운하 지역 아래에 숨겨진 경비가 삼엄한 교도소입니다. 델워터 교도소장이 감독하는 지하감옥은 삼류 사기꾼, 정치적 반역자, 살인자, 그리고 이 땅에서 가장 위험한 범죄자 수십 명이 모여 있는 곳입니다. 최근, 죄수들이 폭동을 일으켜 지하감옥은 아수라장이 되었고, 경비병들은 쫓겨나고 죄수들이 마음대로 활보하고 있습니다."] = "10e3746148a7f37b2c1af2d199833368",
            ["최근에 나랄렉스라고 하는 나이트 엘프 드루이드가 불모의 땅 중심부에 있는 지하 동굴을 발견했습니다. 그 동굴의 샘을 이용해 불모의 땅을 다시 푸르게 만들 수 있을 거라 생각한 나랄렉스는 그 유명한 에메랄드의 꿈의 마력을 끌어들이기 시작했지요. 하지만 그의 예견은 어떻게 돼선지 악몽으로 변해 버렸고 통곡의 동굴은 곧 사납고 무서운 짐승들의 소굴이 되어 버렸습니다. 들리는 바에 의하면 그 미궁 안 어딘가에서 여전히 나랄렉스가 에메랄드의 꿈 가장자리 너머에 갇혀 살고 있다고 합니다."] = "4352ca0c9a3782df4f9b0a23c9c7f9d7",
            ["통곡의 동굴 입구는 불모의 땅에 있는 교차로에서 남서쪽으로 가면 찾을 수 있는 푸른 오아시스에 있습니다."] = "d34171a9fbd911b8f1bf818f71cc3f32",
            ["폐허가 된 도시 스트라솔름은 역병의 숲 북쪽에 있는 동부 역병지대에 있습니다."] = "8d0c3e032d49fe079017a90965f53922",
            ["한 나이트 엘프 마술사의 비밀 분파가 1만 2천 년 전에 지은 고대 도시 엘드레탈라스는 아즈샤라 여왕이 가장 소중히 여기는 마법 비밀을 보호하는 데 사용되었습니다. 세계의 분리로 인해 파괴되기는 했지만 불가사의한 이 도시의 상당 부분이 혈투의 전장이라는 이름을 지니고 으리으리한 모습으로 여전히 남아 있답니다. 서로 뚜렷이 구분되는 이 폐허의 세 지구에는 온갖 종류의 생물들이 출몰하고 있는데, 특히 명가의 유령들이나 사악한 사티로스, 그리고 포악한 오우거들이 많이 나타나고 있습니다."] = "24cd799771f287be14f8060e5444dfa5",
            ["한때 검은무쇠단 드워프들의 수도였던 이 화산 미궁은 이제 불의 군주 라그나로스의 권력 중심지로 쓰이고 있습니다. 돌에서 생명체를 만들어 내는 비밀을 알아낸 라그나로스는 그 누구도 멈출 수 없는 골렘 군단을 만들어 검은바위 산 전체를 정복하는 데 이용하려는 음모를 꾸미고 있습니다. 네파리안과 그의 용 부하들을 물리칠 생각에 사로잡힌 라그나로스는 최후의 승리를 달성하기 위해서라면 그 어떤 극단적인 수단도 가리지 않을 겁니다."] = "9c2b22f32a137854d984166b2aaded4b",
            ["한때 북부 로데론의 보석이라 불리던 스트라솔름은 바로 아서스 왕자가 자신의 스승인 빛의 수호자 우서 경을 배반하고 언데드 역병에 걸린 것으로 간주된 자신의 수백 명의 백성을 살해한 곳입니다. 그 후 아서스는 곧 리치 왕에게 항복했지요. 현재 이 파괴된 도시에는 강력한 리치 켈투자드가 이끄는 언데드 스컬지와 십자군사령관 다스로한이 이끄는 붉은십자군 파견대가 거처하고 있으며, 이 두 진영은 끊임없이 격렬한 전투를 치르고 있습니다."] = "fd70ec87881856186158a19c159addb7",
            ["한때 인간 땅의 금 생산 중심지였던 죽음의 폐광은 이제 데피아즈 결사단이 차지하고 그 어두운 굴을 자신들만의 성소로 만들어 버렸습니다. 소문에 의하면, 이 도적단은 똑똑한 고블린들을 징집해 폐광 바닥에서 뭔가 끔찍한 것을 만드는 걸 돕도록 했다고 합니다만, 그게 무엇인지는 아직 확실하지 않습니다. 들리는 얘기로는, 죽음의 폐광으로 내려가는 길이 조용하고 평온해 보이는 문브룩 마을에 있다고 하더군요."] = "3b08e6def8fe2881c84a302e3f4c7fea",
            ["햇볕에 시들어 버린 이 도시는 그 유별난 무자비함과 암흑 신비술로 악명 높은 성난모래부족 트롤들의 고향입니다. 트롤 전설을 보면 질풍의 술트라제라는 강력한 검 이야기가 나옵니다. 아무리 끔찍한 적에게라도 공포와 나약함을 주입시킬 수 있는 무기라고 합니다. 오래전 이 검이 두 조각이 났다고 하는데, 들리는 소문에 따르면 이 두 조각이 줄파락 성벽 내 어딘가에 있다고 합니다."] = "94fa40981e2a4d5c4b4b0b68b37f782c",
            ["혈투의 전장의 폐허는 페랄라스 중심부에에 있습니다."] = "89054fe6fb8e52df563c9e80702c264a",
        },
        [16543] = {
            ["$c|1이여;여, 사막에서는 몸조심해야 합니다."] = "ba66fca13d25f11aec60b7a40abc3055",
            ["오, 당신이 바로 편지를 발견한 분이군요. 소식을 전해 주셔서 감사합니다. 아마도 가족에 대한 소식이겠죠. 음식과 음료를 드릴 테니 마음껏 드세요."] = "db0fd82a2e87168de7f37ba74147a476",
        },
        [16817] = {
            ["축제는 즐겁게 보내고 있는가?$b$b불꽃지기가 축제를 위한 불을 관리하는 자라면 나는 과거의 축제를 관리하던 역사가라 할 수 있다네. 물론 올해의 축제도 기록할 것이라네. 지금까지는 모든 일이 순조롭게 진행되고 있는 듯 허이, 안 그런가?$b$b자네도 알다시피 축제 기간 동안 불타는 이 모든 축제의 불에는 고유한 힘이 있다네. 우린 우리의 힘을 관리하고 있는 것이네. 하지만, 분명 적의 도시 깊숙한 곳에는 아직도 신성한 불꽃이 타오르고 있을 것이네..."] = "5c66a04a03f0c09ed64da9dc7d5312b6",
        },
        [16818] = {
            ["축제는 즐겁게 보내고 있는가?$b$b불꽃지기가 축제를 위한 불을 관리하는 자라면 나는 과거의 축제를 관리하던 역사가라 할 수 있다네. 물론 올해의 축제도 기록할 것이라네. 지금까지는 모든 일이 순조롭게 진행되고 있는 듯 허이, 안 그런가?$b$b자네도 알다시피 축제 기간 동안 불타는 이 모든 축제의 불에는 고유한 힘이 있다네. 우린 우리의 힘을 관리하고 있는 것이네. 하지만, 분명 적의 도시 깊숙한 곳에는 아직도 신성한 불꽃이 타오르고 있을 것이네..."] = "0b4060988eee47f0f6a9f5aadfb007a3",
        },
        [17209] = {
            ["놀라지 마십시오... 제 그리핀이 완벽한 상태는 아닐지 몰라도 당신을 목적지까지 안전하게 데려다 줄 겁니다. 어느 탑으로 가실 것인지 말씀해 주시겠습니까?"] = "8c3e5d1b67a507ae3bf5d583b20cea89",
        },
        [230317] = {
            ["자비로운 스랄께서는 친절하게도 그의 영역 안에 날 위한 피난처를 마련해 주셨소. 하지만, 너무 오래 머물러 폐를 끼치고 싶지는 않소이다. 나로 인해 우리의 지도자에게 어떤 문제라도 생긴다면 정말 수치스러운 일이 아닐 수 없소."] = "b9ca2ade5c180a21e305ffe165d2771c",
        },
        [230319] = {
            ["시선을 너무 많이 끌지 않도록 하세요. 저는 국왕 폐하께서 알현을 허락해 주시기를 기다리고 있답니다. 기다리는 일만 아니라면 주위에 듬직한 경비병들이 있으니 꽤 안전하다는 생각이 드네요."] = "f555efebf575408048587026c0aa3577",
        },
        [246848] = {
