        },
        [257020] = {
            ["이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?"] = "f203e1b5ce93c4ff82e3d2176bc2b7df",
        },
        [257021] = {
            ["오, 약초채집가로군요. 흠, 보아하니 당신은 아직 잡초나 캐고 있을 것 같으니, 내 제대로 된 약초채집 기술을 몇 가지 가르쳐 주도록 하겠소."] = "5e3106d656d1e19c87aab693c964dd04",
            ["이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?"] = "f203e1b5ce93c4ff82e3d2176bc2b7df",
        },
        [257024] = {
            ["무두질을 배우러 이곳까지 날 찾아오는 일은 드문데... 그래도 당신이 준비가 되었다면 쓸만한 기술은 몇 가지 가르쳐줄 수도 있을 것 같군요."] = "fc47ea411175750a7d770f6b3bb182ef",
            ["이런... 중요한 일을 하던 중이었는데... 날 방해할 만큼 중요한 일이겠지요? 그래, 무슨 일이십니까?"] = "18f39204b5258528e030327d79360cad",
        },
        [258098] = {
            ["영혼들이 당신을 나에게로 이끌어주셨군. 무얼 도와드리면 되겠소?"] = "b2302e24c21151f089da09b386cec376",
            ["원한다면 나는 훈련을 시켜 줄 수 있을 뿐 아니라 자네 머릿속에서 이전에 배운 특성 지식을 지워 버릴 수가 있네. 하지만 이렇게 이전에 배운 특성을 지워 버리는 것은 할 때마다 점점 더 어려운 일이 되기 때문에 점점 더 큰 비용이 들게 된다는 것을 명심해야 하네."] = "4145716fbb2d791ea5392285fe65f1b1",
        },
        [258113] = {
            ["영혼들이 당신을 내게로 이끌어주셨군요. 무얼 도와드리면 되겠습니까?"] = "688528dc8617e517315b28f774aec457",
        },
        [258568] = {
            ["어서 오세요. 오늘은 그냥 구경하러 오셨나요. 아니면 특별히 찾는 물건이라도 있으세요?"] = "a86de99ac7614f683ab7eab24b0a0b93",
            ["어서 오십시오. 오늘은 그냥 구경하시는 겁니까 아니면 특별히 찾으시는 것이 있으십니까?"] = "a86de99ac7614f683ab7eab24b0a0b93",
        },
        [258572] = {
            ["상인들이 파는 물건의 대부분은 아제로스 곳곳에서 찾을 수 있죠. 구하기 힘든 물건이 있던가요? 제게 한정판이 있는데 얼마 안 남은 귀한 물건들이죠. 그대에게는 특별히 싸게 드리도록 하죠."] = "7da2e914119cbb34e9c1d90ccae3ddca",
        },
        [258930] = {
            ["야수에게 가르칠 기술을 배우러 오셨습니까?"] = "530f50b228568790a32debd04b5b6e3e",
        },
        [260093] = {
            ["난 제자들에게 새로운 것을 가르치기 위해 아주 고된 재훈련을 통해서 이전에 배운 것들을 다 잊게 한 적이 많이 있었다네. 이건 매번 할수록 점점 더 어려워지는 일이기 때문에 재훈련을 할 때마다 비용이 점점 더 많이 들지. 내가 자네가 배운 특성을 다 잊어 버리게 해 주길 바라나?"] = "a54fabb9fc0936c92134f8611f4e5e8b",
        },
        [265944] = {
            ["요리란 평생 동안 꾸준히 익혀야 하지요. 우린 같은 열정을 지니고 있는 것 같군요!"] = "6f112dba70f131803f2dc5fb76026cdd",
